package com.example.code.controller

import com.example.code.data.LotteryUpdateRepository
import com.example.code.model.Campsite
import com.example.code.model.Lottery
import com.example.code.model.LotteryCampsite
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test

class LotteryUpdateControllerTest {
    private val owner = "owner-device"
    private val first = Campsite(id = "site-a", ownerId = owner, name = "Pine Creek")
    private val second = Campsite(id = "site-b", ownerId = owner, name = "River Bend")
    private val original = Lottery(
        id = "lottery-a", campsiteId = first.id, campsiteName = first.name, ownerId = owner,
        registrationStart = 1_000L, registrationEnd = 2_000L,
        bookingStart = 3_000L, bookingEnd = 4_000L, winnerCount = 3, waitlistCapacity = 10,
    )
    private fun prepare(
        settings: Lottery = original,
        current: Lottery = original,
        sites: List<Campsite> = listOf(first),
        now: Long = 500L,
        ownerId: String = owner,
    ) = LotteryUpdateController.prepareUpdate(current, ownerId, sites, settings, now)

    @Test fun upcomingLotteryCanChangeAllConfiguration() {
        val updated = prepare(
            settings = original.copy(registrationStart = 1_100L, registrationEnd = 2_100L,
                bookingStart = 3_100L, bookingEnd = 4_100L, winnerCount = 5, waitlistCapacity = 12),
            sites = listOf(first, second),
        )
        assertEquals(original.id, updated.id)
        assertEquals(owner, updated.ownerId)
        assertEquals(listOf(first.id, second.id), updated.campsites.map { it.id })
        assertEquals(1_100L, updated.registrationStart)
        assertEquals(2_100L, updated.registrationEnd)
        assertEquals(3_100L, updated.bookingStart)
        assertEquals(4_100L, updated.bookingEnd)
        assertEquals(5, updated.winnerCount)
        assertEquals(12, updated.waitlistCapacity)
    }

    @Test fun settingsCannotOverwriteIdentityEntrantsOrDrawData() {
        val current = original.copy(waitingListCount = 4, winnerIds = listOf("retained-value"))
        val forged = original.copy(id = "forged", ownerId = "other-owner", waitingListCount = 99,
            status = Lottery.STATUS_DRAWN, winnerIds = listOf("forged-winner"), winnerCount = 5)
        val updated = prepare(settings = forged, current = current)
        assertEquals(current.id, updated.id)
        assertEquals(current.ownerId, updated.ownerId)
        assertEquals(current.waitingListCount, updated.waitingListCount)
        assertEquals(current.status, updated.status)
        assertEquals(current.winnerIds, updated.winnerIds)
        assertEquals(first.id, updated.campsiteId)
        assertEquals(5, updated.winnerCount)
    }

    @Test fun anotherOwnerCannotEdit() {
        assertThrows(IllegalArgumentException::class.java) { prepare(ownerId = "other-owner") }
        assertThrows(IllegalArgumentException::class.java) { prepare(ownerId = "") }
    }

    @Test fun emptyDuplicateForeignAndUnsavedCampsitesAreRejected() {
        for (sites in listOf(emptyList(), listOf(first, first),
            listOf(second.copy(ownerId = "other-owner")), listOf(first.copy(id = "")))) {
            assertThrows(IllegalArgumentException::class.java) { prepare(sites = sites) }
        }
    }

    @Test fun drawnOrExpiredLotteryIsReadOnlyIncludingExactDeadline() {
        assertFalse(LotteryUpdateController.canEdit(original, original.registrationEnd))
        assertThrows(IllegalArgumentException::class.java) { prepare(now = 2_000L) }
        assertThrows(IllegalArgumentException::class.java) {
            prepare(current = original.copy(status = Lottery.STATUS_DRAWN))
        }
    }

    @Test fun newRegistrationDeadlineMustBeFuture() {
        assertThrows(IllegalArgumentException::class.java) {
            prepare(settings = original.copy(registrationEnd = 1_400L), now = 1_500L)
        }
    }

    @Test fun registrationStartLocksAsSoonAsRegistrationOpens() {
        assertThrows(IllegalArgumentException::class.java) {
            prepare(settings = original.copy(registrationStart = 1_100L), now = 1_000L)
        }
        assertEquals(original.registrationStart, prepare(now = 1_500L).registrationStart)
    }

    @Test fun activeLotteryCanChangeDeadlineWinnersAndCapacity() {
        val current = original.copy(waitingListCount = 4)
        val updated = prepare(current = current, now = 1_500L,
            settings = original.copy(registrationEnd = 2_500L, winnerCount = 5, waitlistCapacity = 8))
        assertEquals(2_500L, updated.registrationEnd)
        assertEquals(5, updated.winnerCount)
        assertEquals(8, updated.waitlistCapacity)
        assertEquals(4, updated.waitingListCount)
    }

    @Test fun existingEntrantsLockCampsitesAndStayDates() {
        val current = original.copy(waitingListCount = 1)
        assertThrows(IllegalArgumentException::class.java) { prepare(current = current, sites = listOf(first, second)) }
        assertThrows(IllegalArgumentException::class.java) { prepare(current = current, sites = listOf(second)) }
        assertThrows(IllegalArgumentException::class.java) {
            prepare(current = current, settings = original.copy(bookingEnd = 5_000L))
        }
    }

    @Test fun existingEntrantsStillAllowCurrentCampsiteNameToRefresh() {
        val updated = prepare(current = original.copy(waitingListCount = 2),
            sites = listOf(first.copy(name = "Renamed Pine Creek")))
        assertEquals("Renamed Pine Creek", updated.campsiteName)
    }

    @Test fun capacityCannotBeBelowCurrentEntrants() {
        assertThrows(IllegalArgumentException::class.java) {
            prepare(current = original.copy(waitingListCount = 4), settings = original.copy(waitlistCapacity = 3))
        }
        assertEquals(4, prepare(current = original.copy(waitingListCount = 4),
            settings = original.copy(waitlistCapacity = 4)).waitlistCapacity)
    }

    @Test fun capacityCanBeClearedToUnlimited() {
        assertNull(prepare(current = original.copy(waitingListCount = 100),
            settings = original.copy(waitlistCapacity = null)).waitlistCapacity)
    }

    @Test fun invalidDatesWinnerCountsAndCapacityAreRejected() {
        val invalid = listOf(original.copy(registrationEnd = 1_000L),
            original.copy(bookingStart = 1_900L), original.copy(bookingEnd = 3_000L),
            original.copy(winnerCount = 0), original.copy(waitlistCapacity = 2))
        invalid.forEach { settings ->
            assertThrows(IllegalArgumentException::class.java) { prepare(settings = settings) }
        }
    }

    @Test fun reducingMultipleSitesToOneClearsGroupRepresentation() {
        val current = original.copy(campsites = listOf(
            LotteryCampsite(first.id, first.name), LotteryCampsite(second.id, second.name)))
        val updated = prepare(current = current, sites = listOf(second))
        assertEquals(second.id, updated.campsiteId)
        assertTrue(updated.campsites.isEmpty())
    }

    @Test fun concurrentConfigurationEditIsRejected() {
        val current = original.copy(winnerCount = 4)
        assertThrows(IllegalArgumentException::class.java) {
            LotteryUpdateController.revalidate(original, current, owner, listOf(first), original, 500L)
        }
    }

    @Test fun concurrentJoinIsPreservedAndRechecked() {
        val current = original.copy(waitingListCount = 4)
        assertTrue(LotteryUpdateController.sameConfiguration(original, current))
        val updated = LotteryUpdateController.revalidate(original, current, owner,
            listOf(first), original.copy(winnerCount = 4), 500L)
        assertEquals(4, updated.waitingListCount)
        assertThrows(IllegalArgumentException::class.java) {
            LotteryUpdateController.revalidate(original, current, owner,
                listOf(first), original.copy(waitlistCapacity = 3), 500L)
        }
    }

    @Test fun concurrentJoinPreventsRemovingCampsitesOrChangingStay() {
        val current = original.copy(waitingListCount = 1)
        assertThrows(IllegalArgumentException::class.java) {
            LotteryUpdateController.revalidate(original, current, owner,
                listOf(second), original, 500L)
        }
    }

    @Test fun concurrentDrawOwnershipTransferAndTimeExpiryAreRejected() {
        for (current in listOf(original.copy(status = Lottery.STATUS_DRAWN), original.copy(ownerId = "other"))) {
            assertThrows(IllegalArgumentException::class.java) {
                LotteryUpdateController.revalidate(original, current, owner, listOf(first), original, 500L)
            }
        }
        assertThrows(IllegalArgumentException::class.java) {
            LotteryUpdateController.revalidate(original, original, owner,
                listOf(first), original, original.registrationEnd)
        }
    }

    @Test fun changedLotteryIdentityAndTransferredCampsitesAreRejected() {
        assertThrows(IllegalArgumentException::class.java) {
            LotteryUpdateController.revalidate(original, original.copy(id = "other"), owner,
                listOf(first), original, 500L)
        }
        assertThrows(IllegalArgumentException::class.java) {
            LotteryUpdateController.revalidate(original, original, owner,
                listOf(first.copy(ownerId = "new-owner")), original, 500L)
        }
    }

    @Test fun controllerSubmitsUpdateToExistingDocumentOnlyOnce() = runBlocking {
        var calls = 0
        var saved: Lottery? = null
        val repository = object : LotteryUpdateRepository {
            override suspend fun updateLottery(original: Lottery, ownerId: String, changes: Lottery) {
                calls++
                assertEquals("lottery-a", original.id)
                assertEquals(owner, ownerId)
                saved = changes
            }
        }
        LotteryUpdateController.updateLottery(repository, original, owner,
            listOf(first), original.copy(winnerCount = 4)) { 500L }
        assertEquals(1, calls)
        assertEquals(original.id, saved!!.id)
        assertEquals(4, saved!!.winnerCount)
    }

    @Test fun invalidChangesNeverReachRepositoryAndSaveFailurePropagates() = runBlocking {
        var calls = 0
        val failure = IllegalStateException("Simulated save failure")
        val repository = object : LotteryUpdateRepository {
            override suspend fun updateLottery(original: Lottery, ownerId: String, changes: Lottery) {
                calls++
                throw failure
            }
        }
        assertThrows(IllegalArgumentException::class.java) {
            runBlocking { LotteryUpdateController.updateLottery(repository, original, owner,
                listOf(first), original.copy(winnerCount = 0)) { 500L } }
        }
        assertEquals(0, calls)
        try {
            LotteryUpdateController.updateLottery(repository, original, owner, listOf(first), original) { 500L }
            fail("The save must fail")
        } catch (actual: IllegalStateException) {
            assertSame(failure, actual)
        }
        assertEquals(1, calls)
    }
}
